use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
    out: Vec<int>,
}

impl Tree {
    fn has(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.keys[n as usize]
            if x == k { return true }
            if x < k { n = self.left[n as usize] } else { n = self.right[n as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len() as int
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            let k = self.keys[n as usize]
            if x < k {
                let l = self.left[n as usize]
                if l < 0 {
                    self.left[n as usize] = id
                    return
                }
                n = l
            } else {
                let r = self.right[n as usize]
                if r < 0 {
                    self.right[n as usize] = id
                    return
                }
                n = r
            }
        }
    }

    fn del(self, node: int, x: int) -> int {
        if node < 0 { return -1 }
        let k = self.keys[node as usize]
        if x < k {
            let l = self.left[node as usize]
            self.left[node as usize] = self.del(l, x)
            return node
        }
        if x > k {
            let r = self.right[node as usize]
            self.right[node as usize] = self.del(r, x)
            return node
        }
        let l = self.left[node as usize]
        let r = self.right[node as usize]
        if l < 0 { return r }
        if r < 0 { return l }
        let mut s = r
        while self.left[s as usize] >= 0 { s = self.left[s as usize] }
        let sk = self.keys[s as usize]
        self.keys[node as usize] = sk
        self.right[node as usize] = self.del(r, sk)
        node
    }

    fn height(self, node: int) -> int {
        if node < 0 { return 0 }
        let a = self.height(self.left[node as usize])
        let b = self.height(self.right[node as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, node: int) {
        if node < 0 { return }
        self.walk(self.left[node as usize])
        self.out.push(self.keys[node as usize])
        self.walk(self.right[node as usize])
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1, out: [] }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").map(|p| p.to_string()).collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) {
                t.root = t.del(t.root, x)
                println("ok")
            } else { println("missing") }
        } else if cmd == "inorder" {
            t.out = []
            t.walk(t.root)
            if t.out.len() == 0 { println("<empty>") } else {
                let mut s = ""
                let mut first = true
                for v in t.out.clone() {
                    if !first { s = s + " " }
                    first = false
                    s = s + "${v}"
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                let mut n = t.root
                while t.left[n as usize] >= 0 { n = t.left[n as usize] }
                println("${t.keys[n as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut n = t.root
                while t.right[n as usize] >= 0 { n = t.right[n as usize] }
                println("${t.keys[n as usize]}")
            }
        }
    }
}

